message.content:
{
  "description": "The creature is a large upright chimera shown in right-facing profile, rearing on its hind legs with wings fully spread. It has the head and shaggy mane of a lion at the front top, a deep chest and upper back covered in overlapping feather-like scales, a pair of large broad bird wings extending laterally from the upper torso, and the spotted torso, hindquarters, hind legs and long tufted tail of a large feline. The coloration is predominantly golden-tan and light brown with darker brown feather tips and numerous dark rosette spots on the lower body, legs and tail, set against a plain off-white background.",
  "parts": [
    {
      "part": "head",
      "looks_like": "lion-like head with tan fur, yellow eyes, a dark pinkish-brown nose, white muzzle and chin with whisker dots, and a slightly open mouth",
      "where": "at the top front of the body atop the maned neck, facing right in profile"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded furry ears with darker inner shading, the right ear more visible than the left",
      "where": "on top of the head set within the mane"
    },
    {
      "part": "mane",
      "looks_like": "thick shaggy ruff of long tousled hair in light brown and golden-tan, fuller around the back of the head and neck",
      "where": "encircling the head and neck, extending from the crown down to the feathered chest"
    },
    {
      "part": "legs",
      "looks_like": "two muscular hind legs covered in tan fur with dark rosette spots, bent at the knee and hock in a rearing stance",
      "where": "at the lower middle and rear of the body, supporting the upright posture"
    },
    {
      "part": "feet",
      "looks_like": "two large feline paws with rounded toe pads and short blunt claws, spotted on top",
      "where": "at the bottom ends of the hind legs"
    },
    {
      "part": "tail",
      "looks_like": "long slender tail covered in spotted tan fur ending in a dark brown to black bushy tuft",
      "where": "extending from the rear of the hindquarters and curving in a U-shape to the left"
    },
    {
      "part": "wings",
      "looks_like": "two large broad wings with layered flight feathers, golden-brown on the upper coverts and paler with dark brown tips on the primaries",
      "where": "attached to the upper sides of the torso behind the feathered chest, spread outward to the left and right"
    },
    {
      "part": "feathers",
      "looks_like": "dense overlapping leaf-shaped feathers in shades of tan, golden-brown and dark brown, with darker barring on the outer wing feathers",
      "where": "covering both wings and forming a scaled ruff across the front of the neck and chest"
    },
    {
      "part": "markings",
      "looks_like": "numerous dark brown and black rosette spots and solid dots on a tan background",
      "where": "covering the torso, sides, hindquarters, hind legs and tail"
    }
  ],
  "attached_objects": [],
  "animals": [
    "lion",
    "leopard",
    "eagle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 2,
  "wings": 2,
  "extra_limb_pieces": 0,
  "tails": 1
}
